def longest_k_distinct_substring(s, k):
    counts = {}
    left = best = 0
    for right, letter in enumerate(s):
        counts[letter] = counts.get(letter,0)+1
        while len(counts) > k:
            old = s[left]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
            left += 1
        best = max(best,right-left+1)
    return best

